import 'dart:io';import 'package:flutter/material.dart';import 'package:image_picker/image_picker.dart';import '../services/app_services.dart';
class PostRoom extends StatefulWidget{const PostRoom({super.key});State<PostRoom> createState()=>_Post();}
class _Post extends State<PostRoom>{final f=GlobalKey<FormState>();final title=TextEditingController(),city=TextEditingController(text:'Kathmandu'),area=TextEditingController(),rent=TextEditingController(),deposit=TextEditingController(),desc=TextEditingController();String type='Single';bool furnished=false,bath=false,kitchen=false,parking=false,wifi=false,busy=false;List<XFile> pics=[];
Future<void> pick()async{final p=await ImagePicker().pickMultiImage(imageQuality:82,maxWidth:1800);setState(()=>pics=p.take(8).toList());}
Future<void> submit()async{if(!f.currentState!.validate())return;if(pics.isEmpty){ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content:Text('Add at least one room photo.')));return;}setState(()=>busy=true);try{await RoomService().create(data:{'title':title.text.trim(),'city':city.text.trim(),'area':area.text.trim(),'rent':int.parse(rent.text),'deposit':int.tryParse(deposit.text)??0,'roomType':type,'description':desc.text.trim(),'furnished':furnished,'bathroom':bath,'kitchen':kitchen,'parking':parking,'wifi':wifi},images:pics);if(mounted){ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content:Text('Submitted for moderation.')));Navigator.pop(context);}}catch(e){if(mounted)ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text('$e')));}finally{if(mounted)setState(()=>busy=false);}}
InputDecoration d(String x)=>InputDecoration(labelText:x);Widget build(BuildContext c)=>Scaffold(appBar:AppBar(title:const Text('List your room')),body:Form(key:f,child:ListView(padding:const EdgeInsets.all(16),children:[TextFormField(controller:title,decoration:d('Listing title'),validator:(v)=>v!.isEmpty?'Required':null),const SizedBox(height:10),Row(children:[Expanded(child:TextFormField(controller:city,decoration:d('City'))),const SizedBox(width:10),Expanded(child:TextFormField(controller:area,decoration:d('Area / neighborhood'),validator:(v)=>v!.isEmpty?'Required':null))]),const SizedBox(height:10),Row(children:[Expanded(child:TextFormField(controller:rent,keyboardType:TextInputType.number,decoration:d('Monthly rent'),validator:(v)=>int.tryParse(v??'')==null?'Enter amount':null)),const SizedBox(width:10),Expanded(child:TextFormField(controller:deposit,keyboardType:TextInputType.number,decoration:d('Deposit')))]),DropdownButtonFormField(value:type,decoration:d('Room type'),items:['Single','1BHK','2BHK','Flat','Hostel','Apartment'].map((x)=>DropdownMenuItem(value:x,child:Text(x))).toList(),onChanged:(v)=>setState(()=>type=v!)),TextFormField(controller:desc,maxLines:4,decoration:d('Description')),Wrap(children:[FilterChip(label:const Text('Furnished'),selected:furnished,onSelected:(v)=>setState(()=>furnished=v)),FilterChip(label:const Text('Private bath'),selected:bath,onSelected:(v)=>setState(()=>bath=v)),FilterChip(label:const Text('Kitchen'),selected:kitchen,onSelected:(v)=>setState(()=>kitchen=v)),FilterChip(label:const Text('Parking'),selected:parking,onSelected:(v)=>setState(()=>parking=v)),FilterChip(label:const Text('Wi‑Fi'),selected:wifi,onSelected:(v)=>setState(()=>wifi=v))]),const SizedBox(height:12),OutlinedButton.icon(onPressed:pick,icon:const Icon(Icons.photo_library),label:Text('Select photos (${pics.length}/8)')),if(pics.isNotEmpty)SizedBox(height:110,child:ListView(scrollDirection:Axis.horizontal,children:pics.map((p)=>Padding(padding:const EdgeInsets.only(right:8),child:Image.file(File(p.path),width:120,fit:BoxFit.cover))).toList())),const SizedBox(height:20),FilledButton(onPressed:busy?null:submit,child:Text(busy?'Uploading...':'Submit for approval'))]));}
}
